mapper.select:
select cct.code_type ,cct.code_type_nm ,cct.code_type_nm_s ,to_char(cct.start_date, 'yyyy-mm-dd') as start_date ,to_char(cct.end_date, 'yyyy-mm-dd') as end_date ,cct.create_type_cd ,cct.remark ,cct.create_date ,cct.create_by ,cct.update_date ,cct.update_by from com_code_type cct where 1=1
and cct.code_type = #{CODE_TYPE}
and cct.code_type_nm like #{CODE_TYPE_NM} || '%'

mapper.update:
update com_code_type cct
   set cct.code_type_nm 	= #{CODE_TYPE_NM}
      ,cct.code_type_nm_s	= #{CODE_TYPE_NM_S}
      ,cct.start_date		= TO_DATE(#{START_DATE}, 'YYYY-MM-DD')
      ,cct.end_date			= TO_DATE(#{END_DATE}, 'YYYY-MM-DD')
      ,cct.create_type_cd	= #{CREATE_TYPE_CD}
      ,cct.remark			= #{REMARK}
      ,cct.update_date		= sysdate
      ,cct.update_by		= #{UPDATE_BY}
 where 1=1
   and cct.code_type = #{CODE_TYPE}

mapper.delete:
delete from com_code_type cct
 where 1=1
   and cct.code_type = #{CODE_TYPE}
